<# =====================================================================================
 Schedule Forensics — one-file installer (Tier 1 - 16 GB RAM, no discrete GPU)
 =====================================================================================
 Generated by tools/installer/build_installers.py — DO NOT hand-edit below the
 CONFIG block; regenerate instead. Windows PowerShell 5.1+ compatible.

 What this does (in order, checking before installing — nothing already present is
 reinstalled):
   1. Verifies machine fit (RAM / GPU) for this tier — warns, never blocks.
   2. Ensures Python 3.11+ (winget if missing).
   3. Installs the Schedule Forensics tool into its OWN venv from the wheel embedded
      in this file (no internet needed for the tool itself).
   3b. Deploys the MPXJ converter that native .mpp import needs — copied from a repo
      checkout beside this file if there is one, else downloaded (~17 MB) and SHA-256
      verified against the manifest baked into this installer.
   4. Optionally ensures Java 17+ (also needed to open native .mpp files).
   5. Installs Ollama + this tier's local AI model (skippable — the tool runs fully
      without AI).
   6. Creates the single Desktop + Start-Menu shortcut "Schedule Forensics" (the app stops
      itself and the local AI on Quit — ADR-0193 retired the separate Stop icon, and this
      installer deletes any old Start/Stop pair), plus an uninstaller and a first-run README.

 DATA SOVEREIGNTY: the installed tool is loopback-only (127.0.0.1) — no schedule
 data ever leaves the machine. Internet is used ONLY at install time, for public
 prerequisites (Python / Java / the MPXJ converter / Ollama / the AI model), never by the
 running tool. Set SF_MPXJ_OFFLINE=1 to suppress the MPXJ download on an air-gapped machine.

 Run: right-click this file -> "Run with PowerShell"
      (or:  powershell -ExecutionPolicy Bypass -File <this file>)
===================================================================================== #>

# ------------------------------- TIER CONFIG (edit freely) --------------------------
# Defaults chosen 2026-07-02 per INSTALLER-SPEC.md SS3 (operator authorized autonomous build;
# edit these four lines freely - they are the ONLY tier-specific values in this file).
$TierLabel   = "Tier 1 - 16 GB RAM, no discrete GPU"
$MinRamGB    = 16
$NeedsGpu    = $false
$OllamaModel = "llama3.2:3b"
$ModelDiskGB = 2
# ---------------------------- END TIER CONFIG — SHARED BODY -------------------------

$ErrorActionPreference = "Stop"

# ADR-0299. While $ErrorActionPreference is "Stop", ANY native program that writes to stderr
# raises a TERMINATING error — even when it succeeded. `java -version` prints its banner on
# stderr, and `winget` / `ollama pull` stream progress there, so a step that merely PROBES for
# Java, or an AI install documented as optional, could kill the whole run before the shortcuts,
# uninstaller and README were ever created. That is exactly what happened on the windows CI
# runner (java on PATH -> NativeCommandError -> no DONE), and it stayed invisible because the
# following commands in those steps reset $LASTEXITCODE.
# Run native commands through this helper: it softens the preference for the duration of the
# call and always restores it, streaming output so long downloads still show progress. The
# CALLER decides what a non-zero $LASTEXITCODE means — nothing here aborts implicitly.
function Invoke-SfNative {
    param([Parameter(Mandatory = $true)][scriptblock]$Command)
    $prevEap = $ErrorActionPreference
    try {
        $ErrorActionPreference = "Continue"
        & $Command
    } finally { $ErrorActionPreference = $prevEap }
}

function Install-Main {
# SF_INSTALLER_SMOKE=1: non-interactive CI/self-test mode — temp install root, prompts skipped,
# no shortcuts, no Ollama/Java. Used by the windows-latest smoke workflow; harmless for users.
$Smoke = ($env:SF_INSTALLER_SMOKE -eq "1")
if ($Smoke -and $env:SF_INSTALL_ROOT) { $InstallRoot = $env:SF_INSTALL_ROOT }
elseif ($Smoke) { $InstallRoot = Join-Path ([IO.Path]::GetTempPath()) "SFSmoke\ScheduleForensics" }
else { $InstallRoot = Join-Path $env:LOCALAPPDATA "ScheduleForensics" }
$VenvDir     = Join-Path $InstallRoot "venv"
$AppPort     = 8321
New-Item -ItemType Directory -Force -Path $InstallRoot | Out-Null
Start-Transcript -Path (Join-Path $InstallRoot "install.log") -Append | Out-Null

function Step([string]$msg) { Write-Host "`n==> $msg" -ForegroundColor Cyan }
function Ok([string]$msg)   { Write-Host "    [ok] $msg" -ForegroundColor Green }
function Warn2([string]$msg){ Write-Host "    [!!] $msg" -ForegroundColor Yellow }

Write-Host ""
Write-Host "Schedule Forensics installer — $TierLabel" -ForegroundColor White
Write-Host "Install location: $InstallRoot"

# --- 1. machine fit (warn-only) ------------------------------------------------------
Step "Checking machine fit for this tier"
$ramGB = [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB)
if ($ramGB -lt $MinRamGB) {
    Warn2 "This machine reports ${ramGB} GB RAM; this tier targets ${MinRamGB} GB+. The tool will run; the AI model may be slow or fail to load."
} else { Ok "${ramGB} GB RAM (tier targets ${MinRamGB} GB+)" }
if ($NeedsGpu) {
    $gpus = @(Get-CimInstance Win32_VideoController | Where-Object { $_.AdapterRAM -gt 2GB })
    if ($gpus.Count -eq 0) {
        Warn2 "No discrete GPU detected; this tier's AI model expects one. The model will run on CPU (slow) or fail to load."
    } else { Ok ("GPU detected: " + ($gpus[0].Name)) }
}

# --- 2. Python 3.11+ ------------------------------------------------------------------
Step "Checking Python 3.11+"
function Find-Python {
    foreach ($cand in @(@("py","-3.12"), @("py","-3.11"), @("python",""))) {
        $exe = $cand[0]; $flag = $cand[1]
        if (Get-Command $exe -ErrorAction SilentlyContinue) {
            try {
                if ($flag) { $v = & $exe $flag -c "import sys;print('%d.%d'%sys.version_info[:2])" 2>$null }
                else       { $v = & $exe       -c "import sys;print('%d.%d'%sys.version_info[:2])" 2>$null }
                if ($v -and ([version]$v -ge [version]"3.11")) {
                    # unary comma: PowerShell unrolls a returned 1-element array into a bare
                    # string, and then $py[0] indexes the first CHARACTER ("p" of "python")
                    if ($flag) { return ,@($exe, $flag) } else { return ,@($exe) }
                }
            } catch { }
        }
    }
    return $null
}
$py = Find-Python
if (-not $py) {
    Warn2 "Python 3.11+ not found — installing Python 3.12 via winget (official Python.org package)"
    if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
        throw "winget is not available. Install Python 3.12 manually from python.org, then re-run this installer."
    }
    Invoke-SfNative { winget install --id Python.Python.3.12 --exact --accept-source-agreements --accept-package-agreements --silent --scope user }
    $env:Path = [Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [Environment]::GetEnvironmentVariable("Path","User")
    $py = Find-Python
    if (-not $py) { throw "Python installed but not discoverable on PATH yet — open a NEW window and re-run this installer." }
}
Ok ("Python found: " + ($py -join " "))

# --- 3. the tool, into its own venv, from the wheel embedded below --------------------
Step "Installing Schedule Forensics into its own environment"
if (-not (Test-Path (Join-Path $VenvDir "Scripts\python.exe"))) {
    $py = @($py)  # defensive: never let a bare string reach the indexed invocation below
    if ($py.Count -gt 1) { & $py[0] $py[1] -m venv $VenvDir } else { & $py[0] -m venv $VenvDir }
    Ok "Created venv"
} else { Ok "venv already present (re-using)" }
$venvPy = Join-Path $VenvDir "Scripts\python.exe"

$wheelPath = Join-Path $InstallRoot "schedule_forensics-1.0.215-py3-none-any.whl"
$b64 = $EMBEDDED_WHEEL_B64 -replace "\s", ""
[IO.File]::WriteAllBytes($wheelPath, [Convert]::FromBase64String($b64))
& $venvPy -m pip install --quiet --upgrade pip
& $venvPy -m pip install --quiet --force-reinstall $wheelPath
& $venvPy -c "import schedule_forensics" 2>$null
if ($LASTEXITCODE -ne 0) { throw "The tool failed to import after install — see $InstallRoot\install.log" }
Ok ("Installed " + "schedule_forensics-1.0.215-py3-none-any.whl")
# optional HUD telemetry enhancer (CPU% / temps on Windows) — best-effort, never fatal
try { & $venvPy -m pip install --quiet psutil 2>$null } catch { }

# --- 3b. vendored MPXJ converter (native .mpp support) --------------------------------
# The wheel is pure Python; the 17 MB Java converter is what makes native .mpp import work,
# and without it EVERY .mpp import fails with "MPXJ runner not found".
#
# ADR-0299: it is not embedded (23 MB of base64 x 9 installers, re-committed on every version
# bump), and it must not depend on a repo checkout either — the documented deploy path is a
# SINGLE file downloaded from the GitHub web UI into %USERPROFILE%\Downloads, where the old
# `Split-Path -Parent $PSScriptRoot` lookup resolved to %USERPROFILE%\tools\mpxj, silently
# left .mpp support OFF, and still printed DONE. Several layouts are searched, and failing
# those the pinned file set is downloaded and verified against the baked-in SHA-256 manifest.
#
# TWO RULES THIS BLOCK MUST NEVER BREAK (both mutation-verified — MPXJ-CAPABILITY-REPORT.md):
#  1. NEVER DESTROY AN INSTALLED CONVERTER. Widening the search makes the already-installed
#     copy selectable as a SOURCE, and the copy step clears the destination first — so a re-run
#     would delete the operator's only converter. Hence the self-copy skip, and hence the
#     download stages into a temp folder and is swapped in ONLY once every byte verifies.
#  2. REPORT THE CAPABILITY OF THE DEPLOYED TOOL, NOT THE OUTCOME OF THIS COPY STEP. An
#     upgrade that finds no source but already has a converter installed leaves native .mpp
#     ON; saying "stays OFF" there was simply false, and on a testimony tool a false claim
#     about your own capability is a correctness defect.
$MpxjBaseUrl = "https://raw.githubusercontent.com/polittdj/schedule-manipulation-analysis-tool-experiment/42d92dc9acc98f7d87f19c82dc62be3e5d3c15ca/tools/mpxj"
# The anonymous raw URL above requires a PUBLIC repository. This one went private (DISC-01
# remediation, 2026-08-13), so the fetch is token-aware: with SF_GITHUB_TOKEN (yours) or
# GITHUB_TOKEN (CI's built-in) set, the download switches to the authenticated GitHub contents
# API at the SAME pinned commit. The SHA-256 manifest check below is identical either way —
# the bytes are proven, not the transport.
$MpxjApiBase = "https://api.github.com/repos/polittdj/schedule-manipulation-analysis-tool-experiment/contents/tools/mpxj"
$MpxjRef = "42d92dc9acc98f7d87f19c82dc62be3e5d3c15ca"
$SfGhToken = if ($env:SF_GITHUB_TOKEN) { $env:SF_GITHUB_TOKEN }
             elseif ($env:GITHUB_TOKEN) { $env:GITHUB_TOKEN } else { "" }
$MpxjManifest = @'
5e48d00285e1443a23b545fe1cb68fe7fa153dedb8b9dc341368fd415f8b63b5  MpxjToMspdi.java
1a2c05dc0d4e038a3cb99d57cec3f2fc2a33fbe9993ab4d14069a9a7016363cd  classes/MpxjToMspdi.class
f76b85adb0c00721ae267b7cfde4da7f71d3121cc2160c9fc00c0c89f8c53c8a  lib/SparseBitSet-1.3.jar
6af66595f9f6a7bb58ce66518d6888d40b547c366d2262f06676eee19528ff66  lib/commons-codec-1.20.0.jar
00f93263c267be201b8ae521b44a7137271b16688435340bf629db1bac0a5845  lib/commons-collections4-4.5.0.jar
7d643a2afea8b058b762aa6fb90e5b256f6c729739f8b3784c3370ddc609e88d  lib/commons-io-2.21.0.jar
4eeeae8d20c078abb64b015ec158add383ac581571cddc45c68f0c9ae0230720  lib/commons-lang3-3.18.0.jar
daddea1ea0be0f56978ab3006b8ac92834afeefbd9b7e4e6316fca57df0fa636  lib/commons-logging-1.2.jar
1e56d7b058d28b65abd256b8458e3885b674c1d588fa43cd7d1cbb9c7ef2b308  lib/commons-math3-3.6.1.jar
9f91115f449384886f572bd62c8812ee1004273d4b5c85cac65179ad4c16990f  lib/istack-commons-runtime-4.0.1.jar
adf3f6f513c888f158862b00cf2db51ad6309732105e6de4bfd747670f60a033  lib/jackcess-4.0.10.jar
53ca085f4a150f703f49e1aabd935bd03b43e1ea3d55d135438292af22cef56b  lib/jackson-annotations-2.21.jar
1edd5f2e49dca5f8e4519957c24b7b3050bd1c7ee883920da33cff031ff1f7c0  lib/jackson-core-2.21.1.jar
b011eb5202d9ec889e27f1dcbdf6c63f06a76e7a16c0a1b30c6048d556c9a28e  lib/jackson-databind-2.21.1.jar
b9e24b7dd6e07495562ea96531be3130c96dba4d78e1dfd88adbbdebf4332871  lib/jakarta.activation-2.0.1.jar
b8fb4bee3ff5b5c1ef77144d8411316018d7bbd41fcf1ede0646f7978546b867  lib/jakarta.xml.bind-api-3.0.1.jar
f9a360b939597643b2676e35fc497afb561d20e8a513128a5c0070366db11bbd  lib/jaxb-core-3.0.2.jar
7b3a3784b9c6e343a8d38fc108602ba810177f03f2d8d1e7258b1cef7fd9d4c7  lib/jaxb-runtime-3.0.2.jar
83c4db194424416f1698f2a290f8b09592738dfc5cf5ceb1cc3a5154d2ada256  lib/jgoodies-binding-2.13.0.jar
ddca10c16e1dc7a1b399c14580f0aae23014851e57d224cb96c260e6d649d2ad  lib/jgoodies-common-1.8.1.jar
cfd3298d8720cddfb0545109ccc6ea0ef39eff7e9c40a10ad95c93a65f01c916  lib/jsoup-1.22.1.jar
5b4a0a0cd0e751ded431c162442bdbdd53328d1f8bb2bae5fc1bbeee0f66d80f  lib/log4j-api-2.24.3.jar
b73997d69823a80bb168a5b7b6923450a6897946b3916037d6d6ece782b540cd  lib/mpxj-16.2.0.jar
6c52e876ca75775a11b56e4b36a7541f682827f56406725fcd87560b792ee3d8  lib/poi-5.5.1.jar
aa13625c4a9fc0234caf5e13a6cc3f44ce0d34c5541bb4b1d8ecaf52cb031237  lib/rtfparserkit-1.16.0.jar
b4bcf94fb0a759456e2521724513baec94b78e93127544af162e3cff08d93343  lib/txw2-3.0.2.jar
f80078970a148fda65e4855a48bd5b4540e5a3058f9c7562d0789ed2cb6c8719  setup.ps1
a08844b17f06889397bb4229f79d1ec1de6d4ce1a3bc802d9f6856832d640288  setup.sh
'@
function Resolve-SfPath([string]$p) {
    # Resolve-Path NORMALISES but does not DEREFERENCE: on Windows PowerShell 5.1 a symlink or
    # `mklink /J` junction resolves to its own spelling, so a candidate that merely links to the
    # installed copy compares unequal to the destination and slips past the self-copy skip
    # (ADR-0300 — the bash twin of this destroyed the converter and printed success). Follow one
    # reparse point where the platform exposes a target; the staging below is what makes a miss
    # survivable, so this stays best-effort and never throws.
    try {
        $rp = (Resolve-Path -LiteralPath $p -ErrorAction Stop).ProviderPath
        $item = Get-Item -LiteralPath $rp -Force -ErrorAction Stop
        if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) {
            $t = $item.Target
            if ($t -is [array]) { $t = $t | Select-Object -First 1 }
            if ($t) { return $t }
        }
        return $rp
    } catch { return $p }
}
$destMpxj = Join-Path $InstallRoot "tools\mpxj"
$destReal = Resolve-SfPath $destMpxj
$srcMpxj = $null
# Build the candidate list DEFENSIVELY, one base at a time. `Split-Path -Parent` of a drive root
# ("C:\", a mapped "Z:\") returns "", and `Join-Path` rejects an empty -Path with a parameter-
# binding error, which is TERMINATING regardless of $ErrorActionPreference. In an array literal
# every Join-Path is evaluated eagerly, so an installer saved to a drive root aborted the whole
# run right here — after the venv, before the shortcut, uninstaller and README. Same rule as
# Invoke-SfNative above: a step that merely looks for something must never be able to kill the
# install. (The bash families concatenate strings and cannot throw, so this is PowerShell-only.)
$mpxjCandidates = @()
if ($env:SF_MPXJ_HOME) { $mpxjCandidates += $env:SF_MPXJ_HOME }
foreach ($base in @((Split-Path -Parent $PSScriptRoot), $PSScriptRoot, $PWD.Path)) {
    if ($base) { $mpxjCandidates += (Join-Path $base "tools\mpxj") }
}
foreach ($cand in $mpxjCandidates) {
    if (-not $cand) { continue }
    if (-not (Test-Path (Join-Path $cand "classes\MpxjToMspdi.class"))) { continue }
    # never copy the installed copy over itself — that would delete the only converter
    if ((Resolve-SfPath $cand) -ieq $destReal) { continue }
    $srcMpxj = $cand
    break
}
# Stage the local source COMPLETELY before the destination is touched — the same rule the
# download path follows. The self-copy skip above is a DETECTION, and a detection has to be
# right on every platform to be safe; its bash twin was not. Staging makes a missed self-copy
# harmless rather than fatal, so the two defences are independent (proved by mutation on the
# bash side: with the path guard reverted, staging alone still preserved the converter).
$mpxjStaged = $false
if ($srcMpxj) {
    $stageMpxj = Join-Path $InstallRoot "tools\.mpxj-staging"
    try {
        Remove-Item -Recurse -Force -ErrorAction SilentlyContinue $stageMpxj
        New-Item -ItemType Directory -Force -Path $stageMpxj | Out-Null
        Copy-Item -Recurse -Force -Path (Join-Path $srcMpxj "*") -Destination $stageMpxj
        if (Test-Path (Join-Path $stageMpxj "classes\MpxjToMspdi.class")) { $mpxjStaged = $true }
    } catch { $mpxjStaged = $false }
    if (-not $mpxjStaged) {
        Remove-Item -Recurse -Force -ErrorAction SilentlyContinue $stageMpxj
        Warn2 "MPXJ source at $srcMpxj could not be read — any existing converter is left alone"
    }
}
if ($mpxjStaged) {
    Remove-Item -Recurse -Force -ErrorAction SilentlyContinue $destMpxj
    Move-Item -Force -Path $stageMpxj -Destination $destMpxj
    Ok "MPXJ converter deployed (native .mpp import enabled)"
} elseif (Test-Path (Join-Path $destMpxj "classes\MpxjToMspdi.class")) {
    Ok "MPXJ converter already installed — native .mpp import stays ON (existing copy kept)"
} elseif ($env:SF_MPXJ_OFFLINE -ne "1") {
    Write-Host "    Downloading the MPXJ converter (~17 MB, one time) for native .mpp import..."
    $tmpMpxj = Join-Path $InstallRoot "tools\.mpxj-incoming"
    try {
        # Windows PowerShell 5.1 can still negotiate TLS 1.0/1.1 by default, which every modern
        # host (raw.githubusercontent, aka.ms) refuses — the download would fail with an opaque
        # "connection was closed". OR-ing in Tls12 only ADDS a protocol; it removes nothing.
        try {
            [Net.ServicePointManager]::SecurityProtocol =
                [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
        } catch { }
        Remove-Item -Recurse -Force -ErrorAction SilentlyContinue $tmpMpxj
        New-Item -ItemType Directory -Force -Path $tmpMpxj | Out-Null
        foreach ($line in ($MpxjManifest -split "`n")) {
            $line = $line.Trim()
            if (-not $line) { continue }
            $sha, $rel = $line -split "\s+", 2
            $target = Join-Path $tmpMpxj ($rel -replace "/", "\")
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
            if ($SfGhToken) {
                Invoke-WebRequest -Uri "$MpxjApiBase/$($rel)?ref=$MpxjRef" -OutFile $target `
                    -UseBasicParsing -Headers @{
                        Authorization = "Bearer $SfGhToken"
                        Accept        = "application/vnd.github.raw+json"
                    }
            } else {
                Invoke-WebRequest -Uri "$MpxjBaseUrl/$rel" -OutFile $target -UseBasicParsing
            }
            $got = (Get-FileHash -Algorithm SHA256 -LiteralPath $target).Hash.ToLower()
            if ($got -ne $sha.ToLower()) { throw "checksum mismatch for $rel" }
        }
        if (-not (Test-Path (Join-Path $tmpMpxj "classes\MpxjToMspdi.class"))) {
            throw "converter class missing after download"
        }
        Remove-Item -Recurse -Force -ErrorAction SilentlyContinue $destMpxj
        Move-Item -Force -Path $tmpMpxj -Destination $destMpxj
        Ok "MPXJ converter downloaded and SHA-256 verified (native .mpp import enabled)"
    } catch {
        Remove-Item -Recurse -Force -ErrorAction SilentlyContinue $tmpMpxj
        Warn2 ("MPXJ download failed (" + $_.Exception.Message + ") — native .mpp import is OFF")
        Warn2 "  offline? download the repository ZIP (green 'Code' button -> Download ZIP),"
        Warn2 "  extract it, then re-run this installer from inside the extracted folder"
        Warn2 "  until then: export MSPDI XML from MS Project (File > Save As > XML) instead"
    }
} else {
    Warn2 "no MPXJ converter found — native .mpp import is OFF"
    Warn2 "  to turn it on: set SF_MPXJ_HOME to an MPXJ folder, or download the repository ZIP"
    Warn2 "  (green 'Code' button -> Download ZIP), extract it, and re-run from inside it"
    Warn2 "  until then: export MSPDI XML from MS Project (File > Save As > XML) instead"
}

# a stale 'schedule-forensics' shim from ANOTHER Python (e.g. a conda/miniforge base env)
# can shadow this install in terminals and die with ModuleNotFoundError (operator hit this,
# ADR-0192). The Desktop shortcut always launches the right venv; warn about the impostor.
$shadow = Get-Command schedule-forensics -ErrorAction SilentlyContinue
if ($shadow -and $shadow.Source -and -not $shadow.Source.StartsWith($InstallRoot)) {
    Warn2 ("Typing 'schedule-forensics' in a terminal would run " + $shadow.Source)
    Warn2 ("  — that is another Python's (possibly broken) copy, NOT this install. Use the")
    Warn2 ("  Desktop shortcut, or delete that file to clear the confusion.")
}

# --- 4. Java 17+ (optional — native .mpp only; NO ADMIN required) ---------------------
# ADR-0192: the old path ran the winget OpenJDK MSI, which pops a UAC prompt (operators on
# locked-down machines cannot approve it) and its failure was mis-reported as success. Now:
# detect existing JDKs the way the TOOL's runtime discovery does (including installs that
# are not on PATH), and on consent download Microsoft's PORTABLE ZIP into
# %LOCALAPPDATA%\Programs\Microsoft — user-writable, no elevation, no PATH edits, and
# already one of the folders the runtime java scan searches automatically.
Step "Checking Java 17+ (optional — only needed to open native .mpp files)"
function Find-JavaNoAdmin {
    if (Get-Command java -ErrorAction SilentlyContinue) {
        # `java -version` prints to STDERR even on success — see Invoke-SfNative (ADR-0299).
        $raw = (Invoke-SfNative { java -version 2>&1 }) | Out-String
        if ($raw -match '"(\d+)') {
            $jv = $Matches[1]
            if ([int]$jv -ge 17) { return "java (on PATH)" }
        }
    }
    $roots = @(
        (Join-Path $env:LOCALAPPDATA "Programs\Microsoft"),
        (Join-Path $env:LOCALAPPDATA "Programs\Eclipse Adoptium"),
        (Join-Path $env:LOCALAPPDATA "Programs\Java"),
        (Join-Path $env:ProgramFiles "Microsoft"),
        (Join-Path $env:ProgramFiles "Eclipse Adoptium"),
        (Join-Path $env:ProgramFiles "Java")
    )
    foreach ($root in $roots) {
        if (-not (Test-Path $root)) { continue }
        $hit = Get-ChildItem -Path $root -Directory -ErrorAction SilentlyContinue |
            Where-Object { ($_.Name -match "(?:jdk|jre)-?(\d+)") -and ([int]$Matches[1] -ge 17) } |
            Where-Object { Test-Path (Join-Path $_.FullName "bin\java.exe") } |
            Select-Object -First 1
        if ($hit) { return (Join-Path $hit.FullName "bin\java.exe") }
    }
    return $null
}
$javaWhere = Find-JavaNoAdmin
if ($javaWhere) { Ok "Java 17+ present: $javaWhere (the tool finds it automatically — no PATH change needed)" }
elseif ($Smoke) { Warn2 "Smoke mode: skipping Java offer" }
else {
    $ans = Read-Host "    Java 17+ not found. Download a portable copy now (no admin needed) for native .mpp support? [y/N]"
    if ($ans -match "^[Yy]") {
        try {
            $jdkRoot = Join-Path $env:LOCALAPPDATA "Programs\Microsoft"
            New-Item -ItemType Directory -Force -Path $jdkRoot | Out-Null
            $zip = Join-Path $InstallRoot "microsoft-jdk-17.zip"
            Write-Host "    Downloading Microsoft OpenJDK 17 (portable zip, ~180 MB — no admin prompt)..."
            Invoke-WebRequest -Uri "https://aka.ms/download-jdk/microsoft-jdk-17-windows-x64.zip" -OutFile $zip -UseBasicParsing
            Expand-Archive -Path $zip -DestinationPath $jdkRoot -Force
            Remove-Item -Force -ErrorAction SilentlyContinue $zip
            $javaWhere = Find-JavaNoAdmin
            if ($javaWhere) { Ok "Java 17 ready (no admin needed): $javaWhere" }
            else { Warn2 "Downloaded but java.exe not found where expected — .mpp stays available via MSPDI XML export" }
        } catch {
            Warn2 ("Java download failed (" + $_.Exception.Message + ") — skipped; .mpp files can still be opened after exporting to MSPDI XML from MS Project")
        }
    } else { Warn2 "Skipped — .mpp files can still be opened after exporting to MSPDI XML from MS Project" }
}

# --- 5. Ollama + this tier's local AI model -------------------------------------------
Step "Local AI ($OllamaModel) — the tool runs fully without it (skippable)"
if ($Smoke) { $ans = "n"; Warn2 "Smoke mode: skipping AI install" }
else { $ans = Read-Host "    Install Ollama + pull '$OllamaModel' (~$ModelDiskGB GB download)? [Y/n]" }
if ($ans -notmatch "^[Nn]") {
    # ADR-0299: this step is OPTIONAL, so it must never claim a success it did not get. Both
    # halves used to print [ok] unconditionally — a winget failure (no admin, source down) and
    # a failed pull (disk full, daemon not running, network drop) were both reported as ready,
    # and the operator only found out when the AI features silently did nothing. Same rule as
    # the Java block (ADR-0192): verify, then report what actually happened.
    if (-not (Get-Command ollama -ErrorAction SilentlyContinue)) {
        Invoke-SfNative { winget install --id Ollama.Ollama --exact --accept-source-agreements --accept-package-agreements --silent }
        $env:Path = [Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [Environment]::GetEnvironmentVariable("Path","User")
        if (Get-Command ollama -ErrorAction SilentlyContinue) { Ok "Ollama installed" }
        else { Warn2 "Ollama install failed — skipping the AI model; the tool runs fully without it" }
    } else { Ok "Ollama already present" }
    if (Get-Command ollama -ErrorAction SilentlyContinue) {
        Write-Host "    Pulling $OllamaModel (this is the big download — grab a coffee)..."
        Invoke-SfNative { ollama pull $OllamaModel }
        if ($LASTEXITCODE -eq 0) { Ok "Model ready: $OllamaModel" }
        else { Warn2 "Model download failed — AI prose stays off until you run: ollama pull $OllamaModel" }
    }
} else {
    Warn2 "Skipped — the tool works fully offline; AI prose features stay off until a model is installed"
}

# --- 6. Start / Stop commands, shortcuts, uninstaller, README -------------------------
Step "Creating the Schedule Forensics shortcut, uninstaller, and first-run README"
$startCmd = Join-Path $InstallRoot "Start-ScheduleForensics.cmd"
@"
@echo off
rem Schedule Forensics — start (loopback-only; the browser opens automatically).
start "" "$VenvDir\Scripts\pythonw.exe" -c "from schedule_forensics.launcher import main; main(port=$AppPort)"
"@ | Set-Content -Path $startCmd -Encoding ASCII

$stopCmd = Join-Path $InstallRoot "Stop-ScheduleForensics.cmd"
@"
@echo off
rem Schedule Forensics — graceful stop (asks the local app to shut itself down).
powershell -NoProfile -Command "try { Invoke-RestMethod -Method Post -Uri http://127.0.0.1:$AppPort/api/shutdown -TimeoutSec 5 | Out-Null; Write-Host 'Schedule Forensics stopped.' } catch { Write-Host 'Not running (or already stopped).' }"
timeout /t 3 >nul
"@ | Set-Content -Path $stopCmd -Encoding ASCII

$uninst = Join-Path $InstallRoot "Uninstall-ScheduleForensics.ps1"
@"
# Uninstall Schedule Forensics: removes the app folder + shortcuts.
# Leaves Python / Java / Ollama in place (shared programs); remove the AI model with:
#     ollama rm $OllamaModel
& "$stopCmd" | Out-Null
`$desk = [Environment]::GetFolderPath('Desktop')
`$menu = Join-Path ([Environment]::GetFolderPath('StartMenu')) 'Programs\Schedule Forensics'
Remove-Item -Force -ErrorAction SilentlyContinue (Join-Path `$desk 'Schedule Forensics.lnk')
Remove-Item -Force -ErrorAction SilentlyContinue (Join-Path `$desk 'Start Schedule Forensics.lnk')
Remove-Item -Force -ErrorAction SilentlyContinue (Join-Path `$desk 'Stop Schedule Forensics.lnk')
Remove-Item -Recurse -Force -ErrorAction SilentlyContinue `$menu
Remove-Item -Recurse -Force '$InstallRoot'
Write-Host 'Schedule Forensics removed.'
"@ | Set-Content -Path $uninst -Encoding UTF8

@"
Schedule Forensics — first run
==============================
Start:  double-click "Schedule Forensics" on the Desktop (the ONE icon).
        Your browser opens http://127.0.0.1:$AppPort — everything runs ON THIS MACHINE.
Stop:   just close the browser window / click Quit in the app — the server AND the
        local AI shut themselves down. (Stop-ScheduleForensics.cmd in $InstallRoot
        exists only as a troubleshooting fallback.)
Data:   your schedule files NEVER leave this computer (loopback-only by design).
AI:     enable it in AI Settings inside the app (model installed: $OllamaModel).
.mpp:   opening native .mpp needs Java 17+ (the installer offered it); otherwise
        save-as MSPDI XML in MS Project and open that.
Remove: run Uninstall-ScheduleForensics.ps1 in $InstallRoot.
"@ | Set-Content -Path (Join-Path $InstallRoot "FIRST-RUN-README.txt") -Encoding UTF8

if ($Smoke) {
    Ok "Smoke mode: launchers written to $InstallRoot only (no shortcuts)"
    Stop-Transcript | Out-Null
    Write-Host "SMOKE INSTALL OK" -ForegroundColor Green
    return
}
$shell = New-Object -ComObject WScript.Shell
$desk  = [Environment]::GetFolderPath("Desktop")
$menu  = Join-Path ([Environment]::GetFolderPath("StartMenu")) "Programs\Schedule Forensics"
New-Item -ItemType Directory -Force -Path $menu | Out-Null
# ONE icon (operator, ADR-0193): the app stops ITSELF (and the local AI it manages) when
# the browser window closes or Quit is clicked — a separate Stop icon only confused things.
# The prior installs' Start/Stop desktop icons are removed; Stop-ScheduleForensics.cmd
# stays in the install folder as a troubleshooting fallback.
foreach ($old in @("Start Schedule Forensics.lnk", "Stop Schedule Forensics.lnk")) {
    Remove-Item -Force -ErrorAction SilentlyContinue (Join-Path $desk $old)
    Remove-Item -Force -ErrorAction SilentlyContinue (Join-Path $menu $old)
}
foreach ($dir in @($desk, $menu)) {
    $lnk = $shell.CreateShortcut((Join-Path $dir "Schedule Forensics.lnk"))
    $lnk.TargetPath = (Join-Path $VenvDir "Scripts\pythonw.exe")
    $lnk.Arguments  = "-c `"from schedule_forensics.launcher import main; main(port=$AppPort)`""
    $lnk.WorkingDirectory = $InstallRoot
    $lnk.Description = "Schedule Forensics — starts the tool; closing the browser stops everything"
    $lnk.Save()
}
$unlnk = $shell.CreateShortcut((Join-Path $menu "Uninstall Schedule Forensics.lnk"))
$unlnk.TargetPath = "powershell.exe"
$unlnk.Arguments  = "-ExecutionPolicy Bypass -File `"$uninst`""
$unlnk.Save()
Ok "ONE desktop icon: 'Schedule Forensics' (self-stopping); uninstaller + README in $InstallRoot"

Stop-Transcript | Out-Null
Write-Host ""
Write-Host "DONE — double-click 'Schedule Forensics' on the Desktop to begin." -ForegroundColor Green
Write-Host "(Close the browser window to stop everything, including the local AI.)"
Write-Host "(Everything runs locally at http://127.0.0.1:$AppPort — no data leaves this machine.)"
}

